struct JointRig {std::string id;int head_block=-1,optics_block=-1;EventModel math;};
struct JointShot {std::string id,rig_id;std::int64_t first_pts=0,last_pts=0,time_origin_pts=0;int reference_angles_block=-1;std::vector<int> control_blocks,control_sources,control_offsets;EventModel math;};
struct JointRowLayout {std::vector<int> block_ids;int scene_slot=-1,rig_slot=-1,optics_slot=-1,reference_angles_slot=-1,geometry_slot=-1,advertisement_slot=-1;std::vector<int> control_ids,control_slots,control_offsets,geometry_indices;int geometry_offset=0;int shot_index=-1,material=-1,path=-1,width_slot=-1,width_sign=0;std::int64_t native_pts=0;double frame_time=0;};
class JointEventModel {
 public:
 std::string schema="rinkfit.joint_event_model.v1";int scene_block=0;std::vector<EventParameterBlock> blocks;std::vector<EventMaterial> materials;std::vector<JointRig> rigs;std::vector<JointShot> shots;std::map<std::string,int> shot_map,rig_map;std::map<std::pair<int,int>,std::vector<int>> path_geometry_indices;std::map<std::pair<int,int>,int> path_geometry_offsets;std::map<std::pair<int,int>,std::vector<std::array<double,2>>> path_station_intervals;eventio::Json source_json;
 static JointEventModel load(const std::string& path);
 const std::vector<std::array<double,2>>& station_intervals(int material,int path)const{return path_station_intervals.at({material,path});}
 template<class T>T station_domain(int material,int path,const T&s)const{const auto&intervals=station_intervals(material,path);T best=T(INFINITY);for(const auto&v:intervals){const T a=T(v[0])-s,b=s-T(v[1]);const T g=event_scalar(a)>event_scalar(b)?a:b;if(event_scalar(g)<event_scalar(best))best=g;}return best;}
 bool station_allowed(int material,int path,double s,double tolerance=0)const{return std::isfinite(s)&&station_domain(material,path,s)<=tolerance;}
 JointRowLayout layout(int shot,int material,int path,std::int64_t native_pts,int width_block=-1,int width_sign=0)const;
 std::vector<const double*> pointers(const JointRowLayout& l)const{std::vector<const double*>p;for(auto i:l.block_ids)p.push_back(blocks.at(i).values.data());return p;}
 template<class T> std::array<T,32> global(const JointRowLayout& l,T const*const* p)const{std::array<T,32>g;for(int i=0;i<5;++i)g[i]=p[l.scene_slot][i];for(int i=0;i<15;++i)g[5+i]=p[l.rig_slot][i];for(int i=0;i<12;++i)g[20+i]=p[l.optics_slot][i];return g;}
 template<class T> EventRowLayout legacy_layout(const JointRowLayout& l,std::vector<const T*>& p,const std::array<T,32>& g,T const*const* pars,std::vector<T>& geometry)const{EventRowLayout e;e.global_slot=0;e.material=l.material;e.path=l.path;e.frame_time=l.frame_time;p.push_back(g.data());if(l.geometry_slot>=0){e.geometry_slot=int(p.size());if(l.width_slot<0){if(l.geometry_indices.empty())p.push_back(pars[l.geometry_slot]+l.geometry_offset);else{for(auto i:l.geometry_indices)geometry.push_back(pars[l.geometry_slot][i]);p.push_back(geometry.data());}}else{if(l.geometry_indices.empty()){const auto&source=blocks.at(materials.at(l.material).paths.at(l.path).geometry_block);for(std::size_t i=l.geometry_offset;i<source.values.size();++i)geometry.push_back(pars[l.geometry_slot][i]);}else for(auto i:l.geometry_indices)geometry.push_back(pars[l.geometry_slot][i]);const T shift=T(l.width_sign)*pars[l.width_slot][0];const auto&path=materials.at(l.material).paths.at(l.path);if(path.kind==0){using std::sqrt;const T dx=geometry[2]-geometry[0],dy=geometry[3]-geometry[1],length=sqrt(dx*dx+dy*dy);for(int j:{0,2}){geometry[j]-=shift*dy/length;geometry[j+1]+=shift*dx/length;}}else if(path.kind==1)geometry[path.radius_index]+=shift;else if(path.kind==4)geometry[2]+=shift;else if(path.kind==5){using std::sin;using std::cos;geometry[0]+=shift*sin(geometry[3]);geometry[1]-=shift*cos(geometry[3]);}else throw std::domain_error("paint interfaces require a finite ice stroke");p.push_back(geometry.data());}}if(l.advertisement_slot>=0){e.advertisement_slot=int(p.size());p.push_back(pars[l.advertisement_slot]);}e.control_ids=l.control_ids;for(std::size_t k=0;k<l.control_slots.size();++k){e.control_slots.push_back(int(p.size()));p.push_back(pars[l.control_slots[k]]+l.control_offsets[k]);}return e;}
 template<class T>Vec3<T> world_point(const JointRowLayout& l,const T&s,T const*const* pars,const EventRowLayout&e,const EventModel&math)const{const auto&path=materials.at(l.material).paths.at(l.path);if(path.kind==6||path.kind==7){if(event_scalar(s)<0||event_scalar(s)>1)throw std::domain_error("finite shared print component station");const T*q=pars[e.geometry_slot];if(path.kind==7){using std::cos;using std::sin;const T a=T(path.start_angle)+s*T(path.end_angle-path.start_angle);return EventModel::board_point(q[0]+q[2]*cos(a)+q[3]*sin(a),q[1]+q[4]*sin(a),pars[e.global_slot]);}const int count=l.geometry_indices.empty()?int(blocks.at(materials.at(l.material).paths.at(l.path).geometry_block).values.size())-l.geometry_offset:int(l.geometry_indices.size());const int n=count/2;if(n==1)return EventModel::board_point(q[0],q[1],pars[e.global_slot]);const int segments=path.closed?n:n-1;const T coordinate=s*T(segments);int k=std::min(segments-1,int(std::floor(event_scalar(coordinate))));const T u=coordinate-T(k);const int next=(k+1)%n;return EventModel::board_point(q[2*k]*(T(1)-u)+q[2*next]*u,q[2*k+1]*(T(1)-u)+q[2*next+1]*u,pars[e.global_slot]);}if(path.kind==3&&e.geometry_slot>=0){if(event_scalar(s)<0||event_scalar(s)>1)throw std::domain_error("finite shared-height board station");const T*g=pars[e.global_slot];const T h=pars[e.geometry_slot][0];if(event_scalar(h)<0||event_scalar(h)>1)throw std::domain_error("shared board height fraction");const T arc=EventModel::quarter_arclength(T(1.5707963267948966),g),ll=T(1)-T(2)*g[1],sl=g[0]-T(2)*g[2];T position=s*(T(2)*ll+T(2)*sl+T(4)*arc);if(path.boundary_segment>=0){const T lengths[8]={ll,arc,sl,arc,ll,arc,sl,arc};position=s*lengths[path.boundary_segment];for(int j=0;j<path.boundary_segment;++j)position+=lengths[j];}return EventModel::board_point(position,g[4]*h,g);}if(path.kind==4||path.kind==5){if(event_scalar(s)<0||event_scalar(s)>1)throw std::domain_error("finite half-circle station");const T*q=pars[e.geometry_slot];using std::cos;using std::sin;if(path.kind==4){const T a=q[3]+s*T(3.14159265358979323846);return {q[0]+q[2]*cos(a),q[1]+q[2]*sin(a),T(0)};}const T f=T(1)-T(2)*s;return {q[0]+q[2]*cos(q[3])*f,q[1]+q[2]*sin(q[3])*f,T(0)};}return math.world_point(path,s,pars,e);}
 template<class T> Projection<T> predict_explicit(const JointRowLayout& l,const T& s,const T& row,T const*const* pars)const{
   const auto g=global(l,pars);std::vector<const T*>p;std::vector<T>geometry;const auto e=legacy_layout(l,p,g,pars,geometry);const auto& math=shots.at(l.shot_index).math;const auto time=row_time(T(l.frame_time),g[31],row);auto tr=math.trajectory(time,p.data(),e);tr[0]+=pars[l.reference_angles_slot][0];tr[1]+=pars[l.reference_angles_slot][1];const auto o=zoom_optics(math.optics(g.data()),tr[2]);const auto world=world_point(l,s,p.data(),e,math);return project(world,camera_pose(math.head(g.data()),tr[0],tr[1],o.z),o.intr,o.brown);
 }
 template<class T> EventALProjection<T> predict_for_al(const JointRowLayout& l,const T& s,const T& row,T const*const* pars)const{
   EventALProjection<T> out;const auto g=global(l,pars);std::vector<const T*>p;std::vector<T>geometry;const auto e=legacy_layout(l,p,g,pars,geometry);const auto& math=shots.at(l.shot_index).math;auto tr=math.trajectory(row_time(T(l.frame_time),g[31],row),p.data(),e);tr[0]+=pars[l.reference_angles_slot][0];tr[1]+=pars[l.reference_angles_slot][1];const auto o=zoom_optics(math.optics(g.data()),tr[2]);const auto pose=camera_pose(math.head(g.data()),tr[0],tr[1],o.z);if(!pose.valid()||!valid_rotation(pose.R))return out;const auto world=world_point(l,s,p.data(),e,math);const auto xc=matvec(pose.R,sub(world,pose.C));out.depth=xc[2];if(!(out.depth>T(0))||!finite_array(xc))return out;const Vec2<T>xy={xc[0]/out.depth,xc[1]/out.depth};out.ray_radius_sq=xy[0]*xy[0]+xy[1]*xy[1];out.brown_lower=brown_no_fold_lower_bound(o.brown);const auto d=brown_distort(xy,o.brown);out.uv={o.intr.fx*d[0]+o.intr.cx,o.intr.fy*d[1]+o.intr.cy};out.arithmetic_valid=finite_array(out.uv)&&finite_scalar(out.brown_lower);out.physical_status=out.ray_radius_sq>o.brown.radius_max*o.brown.radius_max?DomainStatus::kOutsideDistortionDomain:(!(out.brown_lower>T(0))?DomainStatus::kDistortionUncertified:DomainStatus::kValid);return out;
 }
 template<class T>T measurement_domain(const JointRowLayout&l,const T&s,T const*const*pars,int kind)const{if(l.width_slot<0)return T(-1);const auto g=global(l,pars);std::vector<const T*>p;std::vector<T>geometry;const auto e=legacy_layout(l,p,g,pars,geometry);const auto&path=materials.at(l.material).paths.at(l.path);if(kind==5){const auto X=world_point(l,s,p.data(),e,shots.at(l.shot_index).math);return EventModel::rink_membership(X[0],X[1],g.data());}if(path.kind==1||path.kind==4){const int ri=path.kind==1?path.radius_index:2;return (T(1e-12)-geometry[ri]+T(l.width_sign+1)*pars[l.width_slot][0])/T(.05);}return T(-1);}
 template<class T>JointVisibility<T> visibility(const JointRowLayout&l,const T&s,const T&row,T const*const*pars)const{const auto g=global(l,pars);std::vector<const T*>p;std::vector<T>geometry;const auto e=legacy_layout(l,p,g,pars,geometry);const auto&math=shots.at(l.shot_index).math;auto tr=math.trajectory(row_time(T(l.frame_time),g[31],row),p.data(),e);tr[0]+=pars[l.reference_angles_slot][0];tr[1]+=pars[l.reference_angles_slot][1];const auto o=zoom_optics(math.optics(g.data()),tr[2]);const auto pose=camera_pose(math.head(g.data()),tr[0],tr[1],o.z);const auto world=world_point(l,s,p.data(),e,math);const auto kind=materials.at(l.material).paths.at(l.path).kind;return joint_visibility(g.data(),pose.C,world,kind==2||kind==3||kind==6||kind==7);}
 EventRootResult certified_projection(EventModel&,const JointRowLayout&,double station,double initial=539.5)const;
 EventRootResult project_rs(const JointRowLayout&,double station,double initial=539.5)const;
 // Full runtime/checkpoint blocks; control_coordinates remains authoritative.
 eventio::Json exact_json()const;
 // Compatibility export expands legacy control mirrors.
 eventio::Json json()const;
 EventModel legacy_snapshot(int shot)const;
};
